inbound = {}
outbound = {}
for n in nodes:
    inbound[n['id']] = 0
    outbound[n['id']] = 0

for e in edges:
    outbound[e['source']] = outbound.get(e['source'], 0) + 1
    inbound[e['target']] = inbound.get(e['target'], 0) + 1

total_conn = {n['id']: inbound[n['id']] + outbound[n['id']] for n in nodes}

# Tier ordering and grouping
tier_order = ['Access', 'Business', 'Data', 'Observability']
tier_nodes = {t: [] for t in tier_order}
for n in nodes:
    tier_nodes[n['tier']].append(n)

# Mermaid-safe IDs
id_map = {}
for n in nodes:
    safe = n['id'].replace('-', '_')
    id_map[n['id']] = safe

# Build Mermaid diagram
mermaid_lines = ['flowchart TD']

# Subgraphs for each tier
for tier in tier_order:
    mermaid_lines.append(f'  subgraph {tier}[{tier} Layer]')
    for n in tier_nodes[tier]:
        mid = id_map[n['id']]
        label = n['label']
        # Escape quotes in label
        label = label.replace('"', '#quot;')
        # Choose shape by type
        if n['type'] == 'infrastructure' and n.get('subtype') == 'database':
            mermaid_lines.append(f'    {mid}[("{label}")]')
        elif n['type'] == 'infrastructure' and n.get('subtype') == 'message_queue':
            mermaid_lines.append(f'    {mid}[/{label}/]')
        elif n['type'] == 'infrastructure' and n.get('subtype') == 'cache':
            mermaid_lines.append(f'    {mid}{{"{label}"}}')
        elif n['type'] == 'observability':
            mermaid_lines.append(f'    {mid}("{label}")')
        elif n['type'] == 'service_mesh_control':
            mermaid_lines.append(f'    {mid[["{label}"]]')
        else:
            mermaid_lines.append(f'    {mid}["{label}"]')
    mermaid_lines.append('  end')

# Edges with styling
for e in edges:
    src = id_map[e['source']]
    tgt = id_map[e['target']]
    ct = e['connection_type']
    proxied = e.get('proxied', False)
    protocol = e['protocol']

    if ct == 'async':
        line = '-.->'
    elif ct == 'sync' and proxied:
        line = '==>'
    else:
        line = '-->'

    # Edge label with protocol
    label = f'|{protocol}|'

    if proxied:
