        if node_type == 'service_mesh_control':
            cls = 'mesh'
        else:
            cls = 'observability'
    else:
        cls = 'data'

    if total_conn[n['id']] >= 6:
        cls += ',hotspot'

    mermaid_lines.append(f'  class {mid} {cls}')

# Edge class styling
mermaid_lines.append('')
mermaid_lines.append('  classDef proxiedEdge stroke:#3498db,stroke-width:3px')
mermaid_lines.append('  classDef asyncEdge stroke:#e67e22,stroke-width:2px,stroke-dasharray:5 5')

mermaid_source = '\n'.join(mermaid_lines)

# Build hotspot info for overlay
hotspots = sorted([(nid, total_conn[nid]) for nid in total_conn], key=lambda x: -x[1])[:5]
hotspot_html = ''
for nid, count in hotspots:
    n = next(x for x in nodes if x['id'] == nid)
    hotspot_html += f'<div class="hotspot-item"><span class="hotspot-dot" style="background:var(--accent-hotspot)"></span><strong>{n["label"]}</strong> &mdash; {inbound[nid]} in / {outbound[nid]} out</div>'

# Tier stats
tier_stats = {}
for t in tier_order:
    tier_stats[t] = len(tier_nodes[t])

